1	//! SPSC ring v2: the in-slot seq, per the design doc's "SPSC
2	//! v2: in-slot seq ring" section.
3	//!
4	//! - v1's protocol with the seq moved into the slot it
5	//!   publishes: every slot opens with a crate-owned
6	//!   [`SLOT_HEADER_BYTES`] header holding the seq word, and the
7	//!   user's message sits behind it in the same cache line. The
8	//!   commit store and the message it publishes then travel on
9	//!   one line, where v1 moves the slot line and, amortised, the
10	//!   seq line.
11	//! - Same region shape as v0, a four-line [`Header`] then the
12	//!   slots, and no seq array. `region_size` is header plus
13	//!   slots.
14	//! - The slot contract changes: `T` must fit `slot_size -
15	//!   SLOT_HEADER_BYTES` and align to at most
16	//!   `SLOT_HEADER_BYTES`, checked at every reserve as the other
17	//!   rings check theirs.
18	//! - Own magic and layout version, so cross-attaching fails
19	//!   toward [`Error::BadMagic`]. Load/store only, `capacity`
20	//!   any power of two down to 1, committed `pos + M + 1`, all
21	//!   as v1.
22	//! - The seq's width is [`Seq`], one alias, so the u32 against
23	//!   native-width measurement is a one-line flip.
24	
25	use core::marker::PhantomData;
26	use core::mem::{align_of, size_of};
27	use core::sync::atomic::{AtomicU32, Ordering};
28	
29	use crate::{CACHE_LINE_SIZE, CacheAligned, Error, USER_WORDS};
30	
31	mod consumer;
32	mod producer;
33	
34	pub use consumer::{Consumer, ReadSlot};
35	pub use producer::{Producer, WriteSlot};
36	
37	/// Layout marker written by [`Ring::init`]; distinct from the
38	/// v0, v1, and MPSC magics so cross-kind attach fails toward
39	/// [`Error::BadMagic`].
40	const MAGIC: u32 = 0x5A43_5233; // "ZCR3"
41	
42	/// Bumped on any change to the v2 region layout; independent
43	/// of the other rings' layout versions.
44	const LAYOUT_VERSION: u32 = 1;
45	
46	/// Capacity bound: `2^30`, as v1 and the MPSC ring.
47	const MAX_CAPACITY: u32 = 1 << 30;
48	
49	/// Bytes the crate owns at the front of every slot: the seq
50	/// word first, the rest reserved.
51	///
52	/// - Sixteen rather than the seq's own width, so the seq can be
53	///   u32 or u64 without moving the body, and so a body may
54	///   align to 16.
55	/// - The body starts here, and a slot of N bytes carries
56	///   `N - SLOT_HEADER_BYTES` bytes of message.
57	pub const SLOT_HEADER_BYTES: usize = 16;
58	
59	/// The seq word's atomic type, the one place its width is
60	/// chosen.
61	///
62	/// - `AtomicU32` is the v1 width, the baseline.
63	/// - `AtomicU64` is the native width on the machines measured,
64	///   the other arm of the width probe.
65	pub type Seq = AtomicU32;
66	
67	/// The integer the seq holds, [`Seq`]'s plain form.
68	pub type SeqInt = u32;
69	
70	const _: () = assert!(size_of::<Seq>() <= SLOT_HEADER_BYTES);
71	const _: () = assert!(align_of::<Seq>() <= SLOT_HEADER_BYTES);
72	const _: () = assert!(SLOT_HEADER_BYTES < CACHE_LINE_SIZE);
73	
74	/// The crate-owned head of every slot.
75	///
76	/// - `seq` at offset 0, the protocol word.
77	/// - The rest reserved, zeroed by init and never read.
78	#[repr(C)]
79	pub struct SlotHeader {
80	    /// The slot's seq word: claimable at `pos`, committed at
81	    /// `pos + M + 1`, released at `pos + M`.
82	    seq: Seq,
83	    /// Reserved, so a wider seq or a later field has room.
84	    _reserved: [u8; SLOT_HEADER_BYTES - size_of::<Seq>()],
85	}
86	
87	const _: () = assert!(size_of::<SlotHeader>() == SLOT_HEADER_BYTES);
88	
89	/// Widen a free-running u32 index to the seq's integer.
90	///
91	/// - The indices stay u32 and wrap there, so the seq holds the
92	///   same values at either width, and a wider seq changes the
93	///   store's width alone.
94	fn seq_of(idx: u32) -> SeqInt {
95	    idx as SeqInt
96	}
97	
98	/// Control block at offset 0 of a v2 region, v1's four-line
99	/// shape as its own type.
100	///
101	/// - line 0: geometry, written by [`Ring::init`] with `magic`
102	///   last (`Release`), read-only thereafter.
103	/// - line 1: `producer_idx`, the producer's private resume
104	///   state.
105	/// - line 2: `consumer_idx`, the consumer's, likewise private.
106	/// - line 3: `user`, app-owned scratch, the v0 contract.
107	/// - Every field is atomic: the region may be mapped by a
108	///   peer at any time.
109	#[repr(C)]
110	pub struct Header {
111	    /// Layout marker ([`MAGIC`]); stored last by init
112	    /// (`Release`), loaded first by attach (`Acquire`).
113	    magic: AtomicU32,
114	    /// Layout version ([`LAYOUT_VERSION`]).
115	    layout_version: AtomicU32,
116	    /// Slot size N in bytes, a [`CACHE_LINE_SIZE`] multiple.
117	    slot_size: AtomicU32,
118	    /// Slot count M, a power of two `<= 2^30`.
119	    capacity: AtomicU32,
120	    /// [`CACHE_LINE_SIZE`] this region was built with.
121	    cache_line_size: AtomicU32,
122	    /// Free-running count of messages committed; producer
123	    /// resume state, not read by the consumer.
124	    producer_idx: CacheAligned<AtomicU32>,
125	    /// Free-running count of messages released; consumer
126	    /// resume state, not read by the producer.
127	    consumer_idx: CacheAligned<AtomicU32>,
128	    /// App-owned scratch line ([`USER_WORDS`] words): zeroed by
129	    /// init, then never touched by the crate.
130	    user: CacheAligned<[AtomicU32; USER_WORDS]>,
131	}
132	
133	const _: () = assert!(size_of::<Header>() == 4 * CACHE_LINE_SIZE);
134	
135	/// A validated view over a v2 ring region; split into the two
136	/// endpoint handles with [`Ring::split`].
137	///
138	/// - Geometry is snapshotted out of the header at init/attach,
139	///   as the other rings do.
140	/// - Region layout: [`Header`], then M slots of N bytes, each
141	///   opening with its [`SlotHeader`].
142	pub struct Ring<'a> {
143	    /// The region's control block.
144	    header: &'a Header,
145	    /// Base of the slot array.
146	    slots: *mut u8,
147	    /// Snapshot of `header.slot_size`.
148	    slot_size: u32,
149	    /// Snapshot of `header.capacity`.
150	    capacity: u32,
151	    /// Slot-position mask (`capacity - 1`).
152	    mask: u32,
153	    _region: PhantomData<&'a [u8]>,
154	}
155	
156	impl<'a> Ring<'a> {
157	    /// Initialize a fresh region and return the ring over it.
158	    ///
159	    /// - `slot_size`: N bytes per slot, a [`CACHE_LINE_SIZE`]
160	    ///   multiple, of which [`SLOT_HEADER_BYTES`] are the
161	    ///   crate's.
162	    /// - `capacity`: M slots, a power of two `<= 2^30`, 1
163	    ///   included.
164	    /// - The region must be [`CACHE_LINE_SIZE`]-aligned and at
165	    ///   least [`region_size`] bytes.
166	    pub fn init(region: &'a mut [u8], slot_size: u32, capacity: u32) -> Result<Self, Error> {
167	        validate_geometry(slot_size, capacity)?;
168	        let len = region.len();
169	        // Taken exactly once, as v0 does: a second
170	        // `as_mut_ptr()` would retag the slice and invalidate
171	        // `header` under Stacked Borrows.
172	        let base = region.as_mut_ptr();
173	        let header = header_ptr(base, len)?;
174	        if (len as u64) < region_size(slot_size, capacity) {
175	            return Err(Error::TooSmall);
176	        }
177	        // SAFETY: alignment + room for the Header checked by
178	        // header_ptr; region is exclusively borrowed for 'a;
179	        // any byte pattern is a valid Header (all-atomic
180	        // fields, plain-byte padding).
181	        let header = unsafe { &*header };
182	        header
183	            .layout_version
184	            .store(LAYOUT_VERSION, Ordering::Relaxed);
185	        header.slot_size.store(slot_size, Ordering::Relaxed);
186	        header.capacity.store(capacity, Ordering::Relaxed);
187	        header
188	            .cache_line_size
189	            .store(CACHE_LINE_SIZE as u32, Ordering::Relaxed);
190	        header.producer_idx.store(0, Ordering::Relaxed);
191	        header.consumer_idx.store(0, Ordering::Relaxed);
192	        for word in header.user.iter() {
193	            word.store(0, Ordering::Relaxed);
194	        }
195	        // SAFETY: in bounds, region.len() >= region_size.
196	        let slots = unsafe { base.add(size_of::<Header>()) };
197	        // `seq[i] = i`: every slot claimable for lap 0, and the
198	        // reserved bytes zeroed.
199	        for i in 0..capacity {
200	            // SAFETY: i < capacity, inside the slot array, and
201	            // the slot header's bytes are ours to write before
202	            // the ring is published.
203	            unsafe {
204	                let slot = slots.add(i as usize * slot_size as usize);
205	                core::ptr::write_bytes(slot, 0, SLOT_HEADER_BYTES);
206	                (*(slot as *const SlotHeader))
207	                    .seq
208	                    .store(seq_of(i), Ordering::Relaxed);
209	            }
210	        }
211	        // Published last: a peer that pre-mapped the region must
212	        // never observe MAGIC before the geometry and seqs it
213	        // relies on.
214	        header.magic.store(MAGIC, Ordering::Release);
215	        Ok(Ring {
216	            header,
217	            slots,
218	            slot_size,
219	            capacity,
220	            mask: capacity - 1,
221	            _region: PhantomData,
222	        })
223	    }
224	
225	    /// Attach to a region another process (or an earlier call)
226	    /// already initialized, validating its header.
227	    ///
228	    /// # Safety
229	    ///
230	    /// - `region` points to `len` bytes of memory that outlive
231	    ///   `'a`, genuinely shared and writable (e.g. a
232	    ///   `MAP_SHARED` mapping).
233	    /// - No other producer attaches if this side will produce;
234	    ///   likewise for the consumer side (SPSC contract).
235	    pub unsafe fn attach(region: *mut u8, len: usize) -> Result<Self, Error> {
236	        let header = header_ptr(region, len)?;
237	        // SAFETY: alignment + room for the Header checked by
238	        // header_ptr; caller guarantees the memory is live and
239	        // shared.
240	        let header = unsafe { &*header };
241	        // Acquire pairs with init's Release store of magic.
242	        if header.magic.load(Ordering::Acquire) != MAGIC {
243	            return Err(Error::BadMagic);
244	        }
245	        if header.layout_version.load(Ordering::Relaxed) != LAYOUT_VERSION {
246	            return Err(Error::BadLayoutVersion);
247	        }
248	        if header.cache_line_size.load(Ordering::Relaxed) != CACHE_LINE_SIZE as u32 {
249	            return Err(Error::BadCacheLine);
250	        }
251	        // Snapshot geometry once; per-op paths never re-read it.
252	        let slot_size = header.slot_size.load(Ordering::Relaxed);
253	        let capacity = header.capacity.load(Ordering::Relaxed);
254	        validate_geometry(slot_size, capacity)?;
255	        if (len as u64) < region_size(slot_size, capacity) {
256	            return Err(Error::TooSmall);
257	        }
258	        // SAFETY: in bounds, len >= region_size.
259	        let slots = unsafe { region.add(size_of::<Header>()) };
260	        Ok(Ring {
261	            header,
262	            slots,
263	            slot_size,
264	            capacity,
265	            mask: capacity - 1,
266	            _region: PhantomData,
267	        })
268	    }
269	
270	    /// Split into the producer and consumer endpoint handles.
271	    ///
272	    /// - Consuming `self` makes each handle exist at most once
273	    ///   per ring per process; cross-process, one producing and
274	    ///   one consuming process is the SPSC contract.
275	    pub fn split(self) -> (Producer<'a>, Consumer<'a>) {
276	        (
277	            Producer::new(
278	                self.header,
279	                self.slots,
280	                self.slot_size,
281	                self.capacity,
282	                self.mask,
283	            ),
284	            Consumer::new(
285	                self.header,
286	                self.slots,
287	                self.slot_size,
288	                self.capacity,
289	                self.mask,
290	            ),
291	        )
292	    }
293	}
294	
295	/// Validate a region base pointer and cast it to the `Header`
296	/// it must start with; shared by [`Ring::init`] /
297	/// [`Ring::attach`].
298	fn header_ptr(base: *mut u8, len: usize) -> Result<*const Header, Error> {
299	    if !(base as usize).is_multiple_of(CACHE_LINE_SIZE) {
300	        return Err(Error::Misaligned);
301	    }
302	    if len < size_of::<Header>() {
303	        return Err(Error::TooSmall);
304	    }
305	    Ok(base as *const Header)
306	}
307	
308	/// Bytes needed for a v2 region with the given geometry: the
309	/// header, then the slots.
310	///
311	/// - Public, as v1's, so a pool that hands out ring segments
312	///   can size its buffers by it.
313	/// - Computed in u64 for the same 32-bit wrap reason as v0's.
314	pub fn region_size(slot_size: u32, capacity: u32) -> u64 {
315	    size_of::<Header>() as u64 + slot_size as u64 * capacity as u64
316	}
317	
318	/// Geometry checks for [`Ring::init`] / [`Ring::attach`].
319	///
320	/// - Slot size as v0, and a line-multiple slot always has room
321	///   for the slot header. Capacity a power of two up to
322	///   [`MAX_CAPACITY`], 1 allowed.
323	fn validate_geometry(slot_size: u32, capacity: u32) -> Result<(), Error> {
324	    if slot_size == 0 || !(slot_size as usize).is_multiple_of(CACHE_LINE_SIZE) {
325	        return Err(Error::BadSlotSize);
326	    }
327	    if capacity == 0 || !capacity.is_power_of_two() || capacity > MAX_CAPACITY {
328	        return Err(Error::BadCapacity);
329	    }
330	    Ok(())
331	}
332	
333	/// Check `T` fits a slot's body; called once per
334	/// `reserve_slot_with` (both endpoints).
335	///
336	/// - The body is the slot behind [`SLOT_HEADER_BYTES`], so the
337	///   size bound is that much smaller than the slot and the
338	///   alignment bound is the header's size, the body's offset
339	///   in a line-aligned slot.
340	/// - Panics on a mismatch, a programming error rather than a
341	///   runtime condition, as the crate's `check_type` does.
342	fn check_body_type<T>(slot_size: u32) {
343	    assert!(
344	        size_of::<T>() <= slot_size as usize - SLOT_HEADER_BYTES,
345	        "T larger than the slot body"
346	    );
347	    assert!(
348	        align_of::<T>() <= SLOT_HEADER_BYTES,
349	        "T alignment exceeds the slot body's"
350	    );
351	}
352	
353	/// The slot header and body for free-running index `idx`.
354	///
355	/// - Returns the slot's `SlotHeader` and the body pointer
356	///   behind it.
357	fn slot_parts<'s>(
358	    slots: *mut u8,
359	    idx: u32,
360	    mask: u32,
361	    slot_size: u32,
362	) -> (&'s SlotHeader, *mut u8) {
363	    let slot = crate::slot_ptr(slots, idx, mask, slot_size);
364	    // SAFETY: the slot is line-aligned and slot_size bytes, so
365	    // the header at its front is in bounds and aligned, and it
366	    // is atomic state shared by design; the body pointer is in
367	    // bounds since SLOT_HEADER_BYTES < CACHE_LINE_SIZE <=
368	    // slot_size.
369	    unsafe { (&*(slot as *const SlotHeader), slot.add(SLOT_HEADER_BYTES)) }
370	}
