1	//! Demo binary: both primitives working across threads,
2	//! with throughput printed — run `cargo run --release`, or
3	//! `cargo install --path . --locked` and run
4	//! `zc-ring-x1-demo`. `-V`/`--version` prints the
5	//! version-of-record so you know exactly which build you
6	//! are testing.
7	//!
8	//! - Part 1, the ring: an SPSC pair moves typed messages
9	//!   in place (reserve → write → commit; reserve → read →
10	//!   release) — first both ends on one thread
11	//!   (the ring's own cost), then one producer thread to
12	//!   one consumer thread: unpinned, pinned to two different
13	//!   physical cores, and pinned to one physical core's two
14	//!   SMT siblings (shared L1/L2, when the CPU has SMT).
15	//!   The SPSC v1 seam-word ring (`spsc1_` lines), the SPSC v2
16	//!   in-slot seq ring (`spsc2_` lines), and the MPSC sibling
17	//!   run beside it at each placement
18	//!   (send_with closure fill), plus a 2-producer + 1-consumer
19	//!   line — the shape only the MPSC ring can run.
20	//! - The depth sweep, last: the ring flavors again at every
21	//!   placement and at depths 1, 2, 8, and 64, one table per
22	//!   placement, so depth and protocol can be told apart.
23	//! - Part 2, the pool: an allocator thread allocs and
24	//!   fills `BufSlot`s and hands them to a freer thread —
25	//!   "send" today is moving the guard (see the README's
26	//!   usage model); getting a buffer implies nothing about
27	//!   when it is sent or freed.
28	//! - The composed form — descriptors through the ring,
29	//!   payloads at rest in pool buffers — runs between them:
30	//!   alloc → into_desc → ring → resolve → free, with the
31	//!   same placement ladder as the raw ring.
32	
33	use std::time::Instant;
34	
35	use zc_ring_x1::{
36	    BufSlot, CACHE_LINE_SIZE, Desc, Empty, Exhausted, Full, MpscRing, Pool, PoolRegistry, Ring,
37	    mpsc_region_size, policy,
38	};
39	use zerocopy::{FromBytes, Immutable, IntoBytes, KnownLayout};
40	
41	/// Messages moved per part.
42	const COUNT: u64 = 1_000_000;
43	
44	/// Ring slots / pool buffers (small on purpose: recycling
45	/// under pressure is the interesting case).
46	const DEPTH: u32 = 64;
47	
48	/// The ring depths the sweep runs, DEPTH among them.
49	const DEPTHS: [u32; 4] = [1, 2, 8, 64];
50	
51	/// The demo message: the sequence number the consumer
52	/// asserts, and `val` — spare payload, doubling as the
53	/// producer id in the multi-producer line.
54	#[derive(FromBytes, IntoBytes, KnownLayout, Immutable, Debug, PartialEq)]
55	#[repr(C)]
56	struct Msg {
57	    seq: u64,
58	    val: u64,
59	}
60	
61	/// Region for the pool, or a v0 ring at DEPTH: biggest header
62	/// (4 lines) + DEPTH one-line slots/buffers.
63	#[repr(C, align(64))]
64	struct Region([u8; 4 * CACHE_LINE_SIZE + DEPTH as usize * CACHE_LINE_SIZE]);
65	
66	/// One cache line of backing store, so a `Vec` of them is a
67	/// line-aligned region of any length, viewed as bytes through
68	/// zerocopy.
69	#[derive(FromBytes, IntoBytes, KnownLayout, Immutable)]
70	#[repr(C, align(64))]
71	struct CacheLine([u8; CACHE_LINE_SIZE]);
72	
73	/// A zeroed, line-aligned heap region of at least `bytes`
74	/// bytes, sized at runtime so a ring's depth is a parameter.
75	///
76	/// - Heap against stack changes nothing the loops measure: the
77	///   region is touched once at init and lives in cache after.
78	fn region(bytes: u64) -> Vec<CacheLine> {
79	    let lines = bytes.div_ceil(CACHE_LINE_SIZE as u64) as usize;
80	    (0..lines)
81	        .map(|_| CacheLine([0; CACHE_LINE_SIZE]))
82	        .collect()
83	}
84	
85	/// Bytes a v0 ring region needs: the four-line header, then
86	/// the slots. v0 exports no size function, its header being a
87	/// fixed shape.
88	fn v0_region_size(slot_size: u32, capacity: u32) -> u64 {
89	    size_of::<zc_ring_x1::Header>() as u64 + slot_size as u64 * capacity as u64
90	}
91	
92	/// Group a count into comma-separated thousands
93	/// (`1234567` → `"1,234,567"`).
94	fn commas(n: u64) -> String {
95	    let digits = n.to_string();
96	    let mut out = String::with_capacity(digits.len() + digits.len() / 3);
97	    for (i, c) in digits.chars().enumerate() {
98	        if i > 0 && (digits.len() - i).is_multiple_of(3) {
99	            out.push(',');
100	        }
101	        out.push(c);
102	    }
103	    out
104	}
105	
106	/// Print one part's line: msgs/sec (comma-grouped) and
107	/// ns/msg from the part's elapsed seconds.
108	fn report(label: &str, secs: f64) {
109	    let rate = commas((COUNT as f64 / secs) as u64);
110	    let ns_per_msg = secs * 1e9 / COUNT as f64;
111	    println!("{label:<46} {rate:>12} msgs/sec  {ns_per_msg:>7.1} ns/msg");
112	}
113	
114	/// Parse a /sys cpu-list string ("0,12" or "0-2,6") into cpu
115	/// numbers; malformed pieces are skipped.
116	#[cfg(target_os = "linux")]
117	fn parse_cpu_list(s: &str) -> Vec<usize> {
118	    let mut out = Vec::new();
119	    for part in s.trim().split(',') {
120	        match part.split_once('-') {
121	            Some((lo, hi)) => {
122	                if let (Ok(lo), Ok(hi)) = (lo.parse::<usize>(), hi.parse::<usize>()) {
123	                    out.extend(lo..=hi);
124	                }
125	            }
126	            None => {
127	                if let Ok(n) = part.parse() {
128	                    out.push(n);
129	                }
130	            }
131	        }
132	    }
133	    out
134	}
135	
136	/// A `(producer cpu, consumer cpu)` pin for a 2t run;
137	/// `None` means the pair is unavailable / leave unpinned.
138	type PinPair = Option<(usize, usize)>;
139	
140	/// Discover two cpu pairs for the pinned 2t runs from
141	/// /sys/devices/system/cpu; `None` when the machine lacks the
142	/// shape (or not Linux).
143	///
144	/// - `.0` — same physical core: cpu0 and its SMT sibling
145	///   (shared L1/L2, the cheapest handoff).
146	/// - `.1` — different physical cores: cpu0 and a core outside
147	///   cpu0's L3 group when one exists (the farthest handoff),
148	///   else any non-sibling core.
149	#[cfg(target_os = "linux")]
150	fn discover_pin_pairs() -> (PinPair, PinPair) {
151	    let read = |path: &str| std::fs::read_to_string(path).ok();
152	    let siblings = read("/sys/devices/system/cpu/cpu0/topology/thread_siblings_list")
153	        .map(|s| parse_cpu_list(&s))
154	        .unwrap_or_default();
155	    let smt = (siblings.len() >= 2).then(|| (siblings[0], siblings[1]));
156	    let online = read("/sys/devices/system/cpu/online")
157	        .map(|s| parse_cpu_list(&s))
158	        .unwrap_or_default();
159	    let l3 = read("/sys/devices/system/cpu/cpu0/cache/index3/shared_cpu_list")
160	        .map(|s| parse_cpu_list(&s))
161	        .unwrap_or_else(|| siblings.clone());
162	    let far = online
163	        .iter()
164	        .copied()
165	        .find(|c| !l3.contains(c))
166	        .or_else(|| {
167	            online
168	                .iter()
169	                .copied()
170	                .find(|c| *c != 0 && !siblings.contains(c))
171	        });
172	    (smt, far.map(|c| (0, c)))
173	}
174	
175	/// Non-Linux stub: no pinned runs.
176	#[cfg(not(target_os = "linux"))]
177	fn discover_pin_pairs() -> (PinPair, PinPair) {
178	    (None, None)
179	}
180	
181	/// Pin the calling thread to `cpu` via sched_setaffinity;
182	/// panics on failure (a demo run with a silently ignored pin
183	/// would report a mislabeled number).
184	#[cfg(target_os = "linux")]
185	fn pin_to_cpu(cpu: usize) {
186	    // SAFETY: cpu_set_t is a plain bitmask; CPU_ZERO/CPU_SET
187	    // initialize it fully before sched_setaffinity reads it.
188	    unsafe {
189	        let mut set: libc::cpu_set_t = std::mem::zeroed();
190	        libc::CPU_ZERO(&mut set);
191	        libc::CPU_SET(cpu, &mut set);
192	        let rc = libc::sched_setaffinity(0, size_of::<libc::cpu_set_t>(), &set);
193	        assert_eq!(rc, 0, "sched_setaffinity({cpu}) failed");
194	    }
195	}
196	
197	/// Non-Linux stub: pinning is a no-op, so only the 1t runs
198	/// reach it (discover_pin_pairs returns no pairs); present
199	/// so the demo compiles everywhere.
200	#[cfg(not(target_os = "linux"))]
201	fn pin_to_cpu(_cpu: usize) {}
202	
203	/// Define the SPSC one-message loops over the ring at `$ring`,
204	/// its region sized by `$size(slot_size, depth)`: `$one_t`
205	/// moves COUNT messages single thread, pinned to cpu 0, and
206	/// `$two_t` moves them producer-thread → consumer-thread (`pin`
207	/// as in [`spsc_ring_one_msg_2t`]), both over a ring of `depth`
208	/// slots; each returns elapsed seconds. The SPSC versions share
209	/// the endpoint surface and differ by path, so one body serves
210	/// them all and the lines read as the protocol seam alone.
211	///
212	/// The 1t loop runs in a scoped thread rather than pinning the
213	/// main thread: spawned threads inherit the main thread's
214	/// affinity mask, which would squeeze every later part onto
215	/// cpu 0.
216	macro_rules! spsc_loops {
217	    ($one_t:ident, $two_t:ident, $ring:path, $size:path) => {
218	        fn $one_t(depth: u32) -> f64 {
219	            let slot = CACHE_LINE_SIZE as u32;
220	            let mut region = region($size(slot, depth));
221	            let (mut producer, mut consumer) = <$ring>::init(region.as_mut_bytes(), slot, depth)
222	                .unwrap() // OK: the region is sized by the ring's own size function and line-aligned
223	                .split();
224	
225	            let start = Instant::now();
226	            std::thread::scope(|s| {
227	                s.spawn(move || {
228	                    pin_to_cpu(0);
229	                    for i in 0..COUNT {
230	                        match producer.reserve_slot_with::<Msg>(|_| false) {
231	                            Ok(mut slot) => {
232	                                slot.seq = i;
233	                                slot.commit();
234	                            }
235	                            Err(Full) => {
236	                                panic!(concat!(
237	                                    stringify!($one_t),
238	                                    ": producer Full SHOULD NOT HAPPEN"
239	                                ));
240	                            }
241	                        }
242	                        match consumer.reserve_slot_with::<Msg>(|_| false) {
243	                            Ok(msg) => {
244	                                assert_eq!(msg.seq, i);
245	                                msg.release();
246	                            }
247	                            Err(Empty) => {
248	                                panic!(concat!(
249	                                    stringify!($one_t),
250	                                    ": consumer Empty SHOULD NOT HAPPEN"
251	                                ));
252	                            }
253	                        }
254	                    }
255	                });
256	            });
257	            start.elapsed().as_secs_f64()
258	        }
259	
260	        fn $two_t(pin: PinPair, depth: u32) -> f64 {
261	            let slot = CACHE_LINE_SIZE as u32;
262	            let mut region = region($size(slot, depth));
263	            let (mut producer, mut consumer) = <$ring>::init(region.as_mut_bytes(), slot, depth)
264	                .unwrap() // OK: the region is sized by the ring's own size function and line-aligned
265	                .split();
266	
267	            let start = Instant::now();
268	            std::thread::scope(|s| {
269	                s.spawn(move || {
270	                    if let Some((p, _)) = pin {
271	                        pin_to_cpu(p);
272	                    }
273	                    for i in 0..COUNT {
274	                        let mut slot = producer.reserve_slot_with::<Msg>(policy::spin).unwrap(); // OK: policy::spin never gives up
275	                        slot.seq = i;
276	                        slot.commit();
277	                    }
278	                });
279	                s.spawn(move || {
280	                    if let Some((_, c)) = pin {
281	                        pin_to_cpu(c);
282	                    }
283	                    for i in 0..COUNT {
284	                        let msg = consumer.reserve_slot_with::<Msg>(policy::spin).unwrap(); // OK: policy::spin never gives up
285	                        assert_eq!(msg.seq, i);
286	                        msg.release();
287	                    }
288	                });
289	            });
290	            start.elapsed().as_secs_f64()
291	        }
292	    };
293	}
294	
295	spsc_loops!(
296	    spsc_ring_one_msg_1t,
297	    spsc_ring_one_msg_2t,
298	    zc_ring_x1::spsc::v0::Ring,
299	    v0_region_size
300	);
301	spsc_loops!(
302	    spsc1_ring_one_msg_1t,
303	    spsc1_ring_one_msg_2t,
304	    zc_ring_x1::spsc::v1::Ring,
305	    zc_ring_x1::spsc::v1::region_size
306	);
307	spsc_loops!(
308	    spsc2_ring_one_msg_1t,
309	    spsc2_ring_one_msg_2t,
310	    zc_ring_x1::spsc::v2::Ring,
311	    zc_ring_x1::spsc::v2::region_size
312	);
313	
314	/// Move COUNT messages single thread through the MPSC ring,
315	/// pinned to cpu 0 — the sibling of spsc_ring_one_msg_1t, so
316	/// the two lines read as the seam between the protocols
317	/// (claim CAS + seq vs load/store); return elapsed seconds.
318	fn mpsc_ring_one_msg_1t(depth: u32) -> f64 {
319	    let slot = CACHE_LINE_SIZE as u32;
320	    let mut region = region(mpsc_region_size(slot, depth));
321	    let (producer, mut consumer) = MpscRing::init(region.as_mut_bytes(), slot, depth)
322	        .unwrap() // OK: the region is sized by mpsc_region_size and line-aligned
323	        .split();
324	
325	    let start = Instant::now();
326	    std::thread::scope(|s| {
327	        s.spawn(move || {
328	            pin_to_cpu(0);
329	            for i in 0..COUNT {
330	                producer.send_with::<Msg>(|_| false, |m| m.seq = i).unwrap(); // OK: room is guaranteed, the consumer drains in lockstep
331	                match consumer.reserve_slot_with::<Msg>(|_| false) {
332	                    Ok(msg) => {
333	                        assert_eq!(msg.seq, i);
334	                        msg.release();
335	                    }
336	                    Err(Empty) => {
337	                        panic!("mpsc_ring_one_msg_1t: consumer Empty SHOULD NOT HAPPEN");
338	                    }
339	                }
340	            }
341	        });
342	    });
343	    start.elapsed().as_secs_f64()
344	}
345	
346	/// Move COUNT messages producer-thread → consumer-thread
347	/// through the MPSC ring — the sibling of
348	/// spsc_ring_one_msg_2t at the same placements, measuring
349	/// what the MPSC protocol costs when you don't need multiple
350	/// producers; return elapsed seconds.
351	///
352	/// - `pin` — `Some((p, c))` pins the producer to cpu `p` and
353	///   the consumer to cpu `c`; `None` lets the scheduler place
354	///   them (the number then depends on where they land).
355	fn mpsc_ring_one_msg_2t(pin: PinPair, depth: u32) -> f64 {
356	    let slot = CACHE_LINE_SIZE as u32;
357	    let mut region = region(mpsc_region_size(slot, depth));
358	    let (producer, mut consumer) = MpscRing::init(region.as_mut_bytes(), slot, depth)
359	        .unwrap() // OK: the region is sized by mpsc_region_size and line-aligned
360	        .split();
361	
362	    let start = Instant::now();
363	    std::thread::scope(|s| {
364	        s.spawn(move || {
365	            if let Some((p, _)) = pin {
366	                pin_to_cpu(p);
367	            }
368	            for i in 0..COUNT {
369	                producer
370	                    .send_with::<Msg>(policy::spin, |m| m.seq = i)
371	                    .unwrap(); // OK: policy::spin never gives up
372	            }
373	        });
374	        s.spawn(move || {
375	            if let Some((_, c)) = pin {
376	                pin_to_cpu(c);
377	            }
378	            for i in 0..COUNT {
379	                let msg = consumer.reserve_slot_with::<Msg>(policy::spin).unwrap(); // OK: policy::spin never gives up
380	                assert_eq!(msg.seq, i);
381	                msg.release();
382	            }
383	        });
384	    });
385	    start.elapsed().as_secs_f64()
386	}
387	
388	/// Move COUNT messages (COUNT/2 per producer) from two
389	/// producer threads into one consumer — the line the SPSC
390	/// ring cannot produce: claim contention on the shared
391	/// producer index. Unpinned (a pinned variant would need a
392	/// third discovered cpu); per-producer FIFO is asserted, the
393	/// interleave is whatever the claim race said. Returns
394	/// elapsed seconds.
395	fn mpsc_ring_one_msg_3t() -> f64 {
396	    let slot = CACHE_LINE_SIZE as u32;
397	    let mut region = region(mpsc_region_size(slot, DEPTH));
398	    let (producer, mut consumer) = MpscRing::init(region.as_mut_bytes(), slot, DEPTH)
399	        .unwrap() // OK: the region is sized by mpsc_region_size and line-aligned
400	        .split();
401	
402	    let start = Instant::now();
403	    std::thread::scope(|s| {
404	        for p in 0..2u64 {
405	            let producer = producer.clone();
406	            s.spawn(move || {
407	                for i in 0..COUNT / 2 {
408	                    producer
409	                        .send_with::<Msg>(policy::spin, |m| {
410	                            m.seq = i;
411	                            m.val = p;
412	                        })
413	                        .unwrap(); // OK: policy::spin never gives up
414	                }
415	            });
416	        }
417	        s.spawn(move || {
418	            let mut next = [0u64; 2];
419	            for _ in 0..COUNT {
420	                let msg = consumer.reserve_slot_with::<Msg>(policy::spin).unwrap(); // OK: policy::spin never gives up
421	                let p = msg.val as usize;
422	                assert_eq!(msg.seq, next[p], "per-producer order broken");
423	                next[p] += 1;
424	                msg.release();
425	            }
426	        });
427	    });
428	    start.elapsed().as_secs_f64()
429	}
430	
431	/// The composed flow on one thread pinned to cpu 0: one pool
432	/// message allocated outside the timed loop; each iteration
433	/// populates it, converts guard → descriptor, rings the
434	/// descriptor across, and resolves the guard back; return
435	/// elapsed seconds.
436	///
437	/// - Isolates messaging cost (into_desc + ring + resolve)
438	///   from the pool cycle — pool_alloc_free_1t reports that
439	///   separately.
440	/// - The guard and the descriptor are the two exclusive
441	///   forms of ownership, so the per-iteration conversion
442	///   cannot hoist: converting *is* the send-side handoff.
443	///   The 2t variant keeps alloc/free per message because
444	///   there ownership genuinely leaves the producer.
445	fn spsc_ring_one_pool_msg_1t() -> f64 {
446	    let mut ring_region = Region([0; size_of::<Region>()]);
447	    let mut pool_region = Region([0; size_of::<Region>()]);
448	    let mut pool = Pool::init(&mut pool_region.0, CACHE_LINE_SIZE as u32, DEPTH).unwrap(); // OK: Region is sized/aligned for the pool header + DEPTH buffers
449	    let mut registry = PoolRegistry::<1>::new();
450	    let pool_id = registry.register(pool.resolver()).unwrap(); // OK: empty capacity-1 registry always has room
451	    let (mut producer, mut consumer) =
452	        Ring::init(&mut ring_region.0, CACHE_LINE_SIZE as u32, DEPTH)
453	            .unwrap() // OK: Region is sized/aligned for the ring header + DEPTH slots
454	            .split();
455	
456	    let start = Instant::now();
457	    std::thread::scope(|s| {
458	        s.spawn(move || {
459	            pin_to_cpu(0);
460	            let mut buf_slot = pool.alloc::<Msg>().unwrap(); // OK: fresh pool, DEPTH buffers free
461	            for i in 0..COUNT {
462	                buf_slot.seq = i;
463	                let desc = registry
464	                    .into_desc(pool_id, buf_slot)
465	                    .map_err(|(_, e)| e)
466	                    .unwrap(); // OK: pool_id came from this registry's register
467	                match producer.reserve_slot_with::<Desc>(|_| false) {
468	                    Ok(mut slot) => {
469	                        *slot = desc;
470	                        slot.commit();
471	                    }
472	                    Err(Full) => {
473	                        panic!("spsc_ring_one_pool_msg_1t: producer Full SHOULD NOT HAPPEN");
474	                    }
475	                }
476	                buf_slot = match consumer.reserve_slot_with::<Desc>(|_| false) {
477	                    Ok(slot) => {
478	                        let desc = *slot;
479	                        slot.release();
480	                        // SAFETY: the desc was consumed into
481	                        // the ring by into_desc above and is
482	                        // resolved exactly once, same thread.
483	                        let msg = unsafe { registry.resolve::<Msg>(desc) }.unwrap(); // OK: desc came from into_desc on this pool
484	                        assert_eq!(msg.seq, i);
485	                        msg
486	                    }
487	                    Err(Empty) => {
488	                        panic!("spsc_ring_one_pool_msg_1t: consumer Empty SHOULD NOT HAPPEN");
489	                    }
490	                };
491	            }
492	            buf_slot.free();
493	        });
494	    });
495	    start.elapsed().as_secs_f64()
496	}
497	
498	/// The composed flow producer-thread → consumer-thread:
499	/// alloc + fill pool messages on the producer, descriptors
500	/// cross the SPSC ring, the consumer resolves and frees;
501	/// return elapsed seconds.
502	///
503	/// - `pin` — `Some((p, c))` pins the producer to cpu `p` and
504	///   the consumer to cpu `c`; `None` lets the scheduler place
505	///   them (the number then depends on where they land).
506	fn spsc_ring_one_pool_msg_2t(pin: PinPair) -> f64 {
507	    let mut ring_region = Region([0; size_of::<Region>()]);
508	    let mut pool_region = Region([0; size_of::<Region>()]);
509	    let mut pool = Pool::init(&mut pool_region.0, CACHE_LINE_SIZE as u32, DEPTH).unwrap(); // OK: Region is sized/aligned for the pool header + DEPTH buffers
510	    let mut registry = PoolRegistry::<1>::new();
511	    let pool_id = registry.register(pool.resolver()).unwrap(); // OK: empty capacity-1 registry always has room
512	    let registry = &registry;
513	    let (mut producer, mut consumer) =
514	        Ring::init(&mut ring_region.0, CACHE_LINE_SIZE as u32, DEPTH)
515	            .unwrap() // OK: Region is sized/aligned for the ring header + DEPTH slots
516	            .split();
517	
518	    let start = Instant::now();
519	    std::thread::scope(|s| {
520	        s.spawn(move || {
521	            if let Some((p, _)) = pin {
522	                pin_to_cpu(p);
523	            }
524	            for i in 0..COUNT {
525	                let mut buf_slot = loop {
526	                    match pool.alloc::<Msg>() {
527	                        Ok(buf_slot) => break buf_slot,
528	                        Err(Exhausted) => std::hint::spin_loop(),
529	                    }
530	                };
531	                buf_slot.seq = i;
532	                let desc = registry
533	                    .into_desc(pool_id, buf_slot)
534	                    .map_err(|(_, e)| e)
535	                    .unwrap(); // OK: pool_id came from this registry's register
536	                let mut slot = producer.reserve_slot_with::<Desc>(policy::spin).unwrap(); // OK: policy::spin never gives up
537	                *slot = desc;
538	                slot.commit();
539	            }
540	        });
541	        s.spawn(move || {
542	            if let Some((_, c)) = pin {
543	                pin_to_cpu(c);
544	            }
545	            for i in 0..COUNT {
546	                let desc = {
547	                    let slot = consumer.reserve_slot_with::<Desc>(policy::spin).unwrap(); // OK: policy::spin never gives up
548	                    let desc = *slot;
549	                    slot.release();
550	                    desc
551	                };
552	                // SAFETY: the desc was consumed into the ring
553	                // by the producer and read after the commit →
554	                // reserve handoff (happens-before); each is
555	                // resolved exactly once.
556	                let msg = unsafe { registry.resolve::<Msg>(desc) }.unwrap(); // OK: descs here only come from the producer's into_desc
557	                assert_eq!(msg.seq, i);
558	                msg.free();
559	            }
560	        });
561	    });
562	    start.elapsed().as_secs_f64()
563	}
564	
565	/// Alloc + fill COUNT messages on an allocator thread,
566	/// free them on a freer thread (guards cross a std
567	/// channel); return elapsed seconds.
568	///
569	/// - `pin` — `Some((a, f))` pins the allocator to cpu `a`
570	///   and the freer to cpu `f`; `None` lets the scheduler
571	///   place them (the number then depends on where they
572	///   land).
573	fn std_mpsc_one_pool_msg_2t(pin: PinPair) -> f64 {
574	    let mut region = Region([0; size_of::<Region>()]);
575	    let mut pool = Pool::init(&mut region.0, CACHE_LINE_SIZE as u32, DEPTH).unwrap(); // OK: Region is sized/aligned for the pool header + DEPTH buffers
576	
577	    let (tx, rx) = std::sync::mpsc::sync_channel::<BufSlot<'_, Msg>>(DEPTH as usize);
578	    let start = Instant::now();
579	    std::thread::scope(|s| {
580	        s.spawn(move || {
581	            if let Some((a, _)) = pin {
582	                pin_to_cpu(a);
583	            }
584	            for i in 0..COUNT {
585	                loop {
586	                    match pool.alloc::<Msg>() {
587	                        Ok(mut buf_slot) => {
588	                            buf_slot.seq = i;
589	                            tx.send(buf_slot).unwrap();
590	                            break;
591	                        }
592	                        Err(Exhausted) => std::hint::spin_loop(),
593	                    }
594	                }
595	            }
596	        });
597	        s.spawn(move || {
598	            if let Some((_, f)) = pin {
599	                pin_to_cpu(f);
600	            }
601	            for i in 0..COUNT {
602	                let buf_slot = rx.recv().unwrap();
603	                assert_eq!(buf_slot.seq, i);
604	                buf_slot.free();
605	            }
606	        });
607	    });
608	    start.elapsed().as_secs_f64()
609	}
610	
611	/// The std-channel flow on one thread pinned to cpu 0: alloc
612	/// a pool message, move its guard through a sync_channel,
613	/// receive and free it; return elapsed seconds.
614	fn std_mpsc_one_pool_msg_1t() -> f64 {
615	    let mut region = Region([0; size_of::<Region>()]);
616	    let mut pool = Pool::init(&mut region.0, CACHE_LINE_SIZE as u32, DEPTH).unwrap(); // OK: Region is sized/aligned for the pool header + DEPTH buffers
617	    let (tx, rx) = std::sync::mpsc::sync_channel::<BufSlot<'_, Msg>>(DEPTH as usize);
618	
619	    let start = Instant::now();
620	    std::thread::scope(|s| {
621	        s.spawn(move || {
622	            pin_to_cpu(0);
623	            for i in 0..COUNT {
624	                let mut buf_slot = pool.alloc::<Msg>().unwrap(); // OK: alloc+free per iteration, DEPTH never exceeded
625	                buf_slot.seq = i;
626	                tx.send(buf_slot).unwrap(); // OK: capacity DEPTH, at most one in flight
627	                let buf_slot = rx.recv().unwrap(); // OK: just sent on this thread
628	                assert_eq!(buf_slot.seq, i);
629	                buf_slot.free();
630	            }
631	        });
632	    });
633	    start.elapsed().as_secs_f64()
634	}
635	
636	/// Alloc → write → free COUNT messages on one thread pinned
637	/// to cpu 0 — the pool's own cost, no channel, no second
638	/// thread; return elapsed seconds.
639	///
640	/// Runs in a scoped thread like the other pinned parts, so
641	/// the main thread's affinity stays untouched.
642	fn pool_alloc_free_1t() -> f64 {
643	    let mut region = Region([0; size_of::<Region>()]);
644	    let mut pool = Pool::init(&mut region.0, CACHE_LINE_SIZE as u32, DEPTH).unwrap(); // OK: Region is sized/aligned for the pool header + DEPTH buffers
645	
646	    let start = Instant::now();
647	    std::thread::scope(|s| {
648	        s.spawn(move || {
649	            pin_to_cpu(0);
650	            for i in 0..COUNT {
651	                let mut buf_slot = pool.alloc::<Msg>().unwrap(); // OK: alloc+free per iteration, DEPTH never exceeded
652	                buf_slot.seq = i;
653	                std::hint::black_box(buf_slot.seq);
654	                buf_slot.free();
655	            }
656	        });
657	    });
658	    start.elapsed().as_secs_f64()
659	}
660	
661	/// The same loop through the global allocator (Box::new →
662	/// write → drop) for comparison, pinned to cpu 0; return
663	/// elapsed seconds.
664	///
665	/// Runs in a scoped thread like the other pinned parts, so
666	/// the main thread's affinity stays untouched.
667	fn global_alloc_free_1t() -> f64 {
668	    let start = Instant::now();
669	    std::thread::scope(|s| {
670	        s.spawn(move || {
671	            pin_to_cpu(0);
672	            for i in 0..COUNT {
673	                let mut buf = std::hint::black_box(Box::new(Msg { seq: 0, val: 0 }));
674	                buf.seq = i;
675	                std::hint::black_box(buf.seq);
676	                drop(buf);
677	            }
678	        });
679	    });
680	    start.elapsed().as_secs_f64()
681	}
682	
683	/// One ring flavor's stream loops, for the depth sweep.
684	struct StreamFlavor {
685	    /// The label the table carries.
686	    name: &'static str,
687	    /// The smallest depth the protocol runs at: the MPSC ring
688	    /// collapses at 1 (`notes/bugs.md`), so its cell there is
689	    /// printed as `-`.
690	    min_depth: u32,
691	    /// The single-thread loop at a depth.
692	    one_t: fn(u32) -> f64,
693	    /// The two-thread loop at a placement and a depth.
694	    two_t: fn(PinPair, u32) -> f64,
695	}
696	
697	/// The flavors the sweep runs, in table order.
698	const STREAM_FLAVORS: [StreamFlavor; 4] = [
699	    StreamFlavor {
700	        name: "spsc",
701	        min_depth: 1,
702	        one_t: spsc_ring_one_msg_1t,
703	        two_t: spsc_ring_one_msg_2t,
704	    },
705	    StreamFlavor {
706	        name: "spsc-v1",
707	        min_depth: 1,
708	        one_t: spsc1_ring_one_msg_1t,
709	        two_t: spsc1_ring_one_msg_2t,
710	    },
711	    StreamFlavor {
712	        name: "spsc-v2",
713	        min_depth: 1,
714	        one_t: spsc2_ring_one_msg_1t,
715	        two_t: spsc2_ring_one_msg_2t,
716	    },
717	    StreamFlavor {
718	        name: "mpsc",
719	        min_depth: 2,
720	        one_t: mpsc_ring_one_msg_1t,
721	        two_t: mpsc_ring_one_msg_2t,
722	    },
723	];
724	
725	/// Where a sweep row's threads sit.
726	enum SweepPlacement {
727	    /// Both ends on one thread, pinned to cpu 0.
728	    OneT,
729	    /// Producer and consumer threads at `PinPair`.
730	    TwoT(PinPair),
731	}
732	
733	/// Run every flavor at every depth of [`DEPTHS`] at each
734	/// placement the machine offers, and print one markdown table
735	/// per placement, ns per message in the depth columns.
736	///
737	/// - The same loops as the lines above, so a `d=64` cell and
738	///   the matching line agree up to run noise.
739	/// - Depth 1 is lockstep: every message is its own handoff, so
740	///   streaming there costs what a round trip does.
741	fn depth_sweep(smt: PinPair, far: PinPair) {
742	    let mut placements = vec![
743	        ("1t core 0".to_string(), SweepPlacement::OneT),
744	        ("2t unpinned".to_string(), SweepPlacement::TwoT(None)),
745	    ];
746	    if let Some((p, c)) = far {
747	        placements.push((format!("2t diff cores {p}+{c}"), SweepPlacement::TwoT(far)));
748	    }
749	    if let Some((p, c)) = smt {
750	        placements.push((format!("2t same core {p}+{c}"), SweepPlacement::TwoT(smt)));
751	    }
752	    let depth_list: Vec<String> = DEPTHS.iter().map(|d| d.to_string()).collect();
753	    println!(
754	        "depth sweep: {} messages per cell, ns/msg at depths {}",
755	        commas(COUNT),
756	        depth_list.join(", ")
757	    );
758	    for (label, placement) in &placements {
759	        println!();
760	        let mut header = format!("| {label:<22} |");
761	        let mut sep = format!("|{}|", "-".repeat(24));
762	        for d in &depth_list {
763	            header.push_str(&format!(" {:>7} |", format!("d={d}")));
764	            sep.push_str(&format!("{}:|", "-".repeat(8)));
765	        }
766	        println!("{header}");
767	        println!("{sep}");
768	        for flavor in &STREAM_FLAVORS {
769	            let mut row = format!("| {:<22} |", flavor.name);
770	            for &depth in &DEPTHS {
771	                if depth < flavor.min_depth {
772	                    row.push_str(&format!(" {:>7} |", "-"));
773	                    continue;
774	                }
775	                let secs = match placement {
776	                    SweepPlacement::OneT => (flavor.one_t)(depth),
777	                    SweepPlacement::TwoT(pin) => (flavor.two_t)(*pin, depth),
778	                };
779	                row.push_str(&format!(" {:>7.1} |", secs * 1e9 / COUNT as f64));
780	            }
781	            println!("{row}");
782	        }
783	    }
784	}
785	
786	/// Run both parts and print their throughput, then the depth
787	/// sweep; `-V` / `--version` prints the version-of-record and
788	/// exits.
789	fn main() {
790	    let banner = concat!(env!("CARGO_PKG_NAME"), " ", env!("CARGO_PKG_VERSION"));
791	    println!("{banner}");
792	    if std::env::args().any(|a| a == "-V" || a == "--version") {
793	        return;
794	    }
795	    println!("demo: {} messages each, depth {DEPTH}", commas(COUNT));
796	    let (smt, far) = discover_pin_pairs();
797	
798	    // Alloc/free baselines, then message flows — like
799	    // compares with like within each block.
800	    report("pool_alloc_free_1t (core 0):", pool_alloc_free_1t());
801	    report("global_alloc_free_1t (core 0):", global_alloc_free_1t());
802	
803	    // Single thread, core 0.
804	    println!();
805	    report(
806	        "spsc_ring_one_msg_1t (core 0):",
807	        spsc_ring_one_msg_1t(DEPTH),
808	    );
809	    report(
810	        "spsc1_ring_one_msg_1t (core 0):",
811	        spsc1_ring_one_msg_1t(DEPTH),
812	    );
813	    report(
814	        "spsc2_ring_one_msg_1t (core 0):",
815	        spsc2_ring_one_msg_1t(DEPTH),
816	    );
817	    report(
818	        "mpsc_ring_one_msg_1t (core 0):",
819	        mpsc_ring_one_msg_1t(DEPTH),
820	    );
821	    report(
822	        "spsc_ring_one_pool_msg_1t (core 0):",
823	        spsc_ring_one_pool_msg_1t(),
824	    );
825	    report(
826	        "std_mpsc_one_pool_msg_1t (core 0):",
827	        std_mpsc_one_pool_msg_1t(),
828	    );
829	
830	    // Two threads, scheduler-placed.
831	    println!();
832	    report(
833	        "spsc_ring_one_msg_2t (unpinned):",
834	        spsc_ring_one_msg_2t(None, DEPTH),
835	    );
836	    report(
837	        "spsc1_ring_one_msg_2t (unpinned):",
838	        spsc1_ring_one_msg_2t(None, DEPTH),
839	    );
840	    report(
841	        "spsc2_ring_one_msg_2t (unpinned):",
842	        spsc2_ring_one_msg_2t(None, DEPTH),
843	    );
844	    report(
845	        "mpsc_ring_one_msg_2t (unpinned):",
846	        mpsc_ring_one_msg_2t(None, DEPTH),
847	    );
848	    report(
849	        "spsc_ring_one_pool_msg_2t (unpinned):",
850	        spsc_ring_one_pool_msg_2t(None),
851	    );
852	    report(
853	        "std_mpsc_one_pool_msg_2t (unpinned):",
854	        std_mpsc_one_pool_msg_2t(None),
855	    );
856	
857	    // Three threads (2 producers + 1 consumer): the
858	    // multi-producer line only the MPSC ring can run.
859	    report(
860	        "mpsc_ring_one_msg_3t (2p+1c unpinned):",
861	        mpsc_ring_one_msg_3t(),
862	    );
863	
864	    // Two threads, different physical cores.
865	    println!();
866	    match far {
867	        Some((p, c)) => {
868	            report(
869	                &format!("spsc_ring_one_msg_2t (diff cores {p}+{c}):"),
870	                spsc_ring_one_msg_2t(far, DEPTH),
871	            );
872	            report(
873	                &format!("spsc1_ring_one_msg_2t (diff cores {p}+{c}):"),
874	                spsc1_ring_one_msg_2t(far, DEPTH),
875	            );
876	            report(
877	                &format!("spsc2_ring_one_msg_2t (diff cores {p}+{c}):"),
878	                spsc2_ring_one_msg_2t(far, DEPTH),
879	            );
880	            report(
881	                &format!("mpsc_ring_one_msg_2t (diff cores {p}+{c}):"),
882	                mpsc_ring_one_msg_2t(far, DEPTH),
883	            );
884	            report(
885	                &format!("spsc_ring_one_pool_msg_2t (diff cores {p}+{c}):"),
886	                spsc_ring_one_pool_msg_2t(far),
887	            );
888	            report(
889	                &format!("std_mpsc_one_pool_msg_2t (diff cores {p}+{c}):"),
890	                std_mpsc_one_pool_msg_2t(far),
891	            );
892	        }
893	        None => {
894	            println!("2t diff-cores runs:");
895	            println!("  skipped, only one core found");
896	        }
897	    }
898	
899	    // Two threads, one physical core (SMT siblings).
900	    println!();
901	    match smt {
902	        Some((p, c)) => {
903	            report(
904	                &format!("spsc_ring_one_msg_2t (same core {p}+{c}):"),
905	                spsc_ring_one_msg_2t(smt, DEPTH),
906	            );
907	            report(
908	                &format!("spsc1_ring_one_msg_2t (same core {p}+{c}):"),
909	                spsc1_ring_one_msg_2t(smt, DEPTH),
910	            );
911	            report(
912	                &format!("spsc2_ring_one_msg_2t (same core {p}+{c}):"),
913	                spsc2_ring_one_msg_2t(smt, DEPTH),
914	            );
915	            report(
916	                &format!("mpsc_ring_one_msg_2t (same core {p}+{c}):"),
917	                mpsc_ring_one_msg_2t(smt, DEPTH),
918	            );
919	            report(
920	                &format!("spsc_ring_one_pool_msg_2t (same core {p}+{c}):"),
921	                spsc_ring_one_pool_msg_2t(smt),
922	            );
923	            report(
924	                &format!("std_mpsc_one_pool_msg_2t (same core {p}+{c}):"),
925	                std_mpsc_one_pool_msg_2t(smt),
926	            );
927	        }
928	        None => {
929	            println!("2t same-core runs:");
930	            println!("  skipped, no SMT sibling found");
931	        }
932	    }
933	
934	    // The depth sweep, the ring flavors at every placement.
935	    println!();
936	    depth_sweep(smt, far);
937	}
